<script lang="ts">
  interface Props {
    label: string;
    checked: boolean;
    disabled?: boolean;
    dataTestId?: string;
    ontoggle?: () => void;
  }

  let {
    label,
    checked = $bindable(),
    disabled = false,
    dataTestId,
    ontoggle
  }: Props = $props();

  function handleClick() {
    if (!disabled) {
      ontoggle?.();
    }
  }
</script>

<button
  class="settings-expander__toggle-btn"
  class:active={checked}
  class:active-disabled={checked && disabled}
  onclick={handleClick}
  {disabled}
  data-testid={dataTestId}
>
  {label}
</button>

